/// Recursive radix-2 Cooley–Tukey FFT over complex samples `(re, im)`.
/// `input.len()` must be a power of two.
pub fn fft(input: &[(f64, f64)]) -> Vec<(f64, f64)> {
    let n = input.len();
    if n <= 1 {
        return input.to_vec();
    }
    assert!(n & (n - 1) == 0, "fft: length must be a power of two");
    let even = fft(&input.iter().step_by(2).copied().collect::<Vec<_>>());
    let odd = fft(&input.iter().skip(1).step_by(2).copied().collect::<Vec<_>>());
    let mut out = vec![(0.0, 0.0); n];
    for k in 0..n / 2 {
        let angle = -2.0 * std::f64::consts::PI * k as f64 / n as f64;
        let (tw_re, tw_im) = (angle.cos(), angle.sin());
        let (o_re, o_im) = odd[k];
        let t = (tw_re * o_re - tw_im * o_im, tw_re * o_im + tw_im * o_re);
        let (e_re, e_im) = even[k];
        out[k] = (e_re + t.0, e_im + t.1);
        out[k + n / 2] = (e_re - t.0, e_im - t.1);
    }
    out
}
